/* Native confirmations and source manager, included after the query helpers. */
static Evas_Object *source_win,*source_list,*source_url,*source_info;
static char source_digest[65];
typedef struct {int index,enabled,known;char *url,*id,*name;} Source;
static Eina_List *source_rows;static Source *source_selected;
typedef struct {char *action,*json;Evas_Object *popup;} Pending;
static void json_string(FILE *file,const char *s){fputc('"',file);for(;*s;s++){if(*s=='"'||*s=='\\')fputc('\\',file);if((unsigned char)*s<32)fprintf(file,"\\u%04x",(unsigned char)*s);else fputc(*s,file);}fputc('"',file);}
static void pending_free(Pending *p){evas_object_del(p->popup);free(p->action);free(p->json);free(p);}
static void cancel_operation(void *data,Evas_Object *obj,void *event){(void)obj;(void)event;pending_free(data);}
static void confirm_operation(void *data,Evas_Object *obj,void *event){(void)obj;(void)event;Pending *p=data;if(operation_request.exe){pending_free(p);return;}char path[]="/tmp/enaptic-request-XXXXXX";int fd=mkstemp(path);if(fd<0){label(details,"Could not create operation request.");pending_free(p);return;}FILE *file=fdopen(fd,"w");if(!file){close(fd);unlink(path);pending_free(p);return;}fputs(p->json,file);fclose(file);int kind=!strcmp(p->action,"apply")?4:!strcmp(p->action,"reload")?5:!strcmp(p->action,"source")?6:7;
 if(request_start(&operation_request,kind,p->action,kind==5?NULL:path)){operation_request.input_file=strdup(path);label(details,"Authenticating… Native operation progress appears here.");drop_review();controls();}else{unlink(path);label(details,"Could not start authenticated helper.");}pending_free(p);}
static void ask_operation(const char *action,const char *json,const char *message){if(operation_request.exe||plan_request.exe)return;Pending *p=calloc(1,sizeof(*p));p->action=strdup(action);p->json=strdup(json);p->popup=elm_popup_add(win);elm_object_part_text_set(p->popup,"title,text",!strcmp(action,"apply")?"Apply reviewed package changes?":"Review system operation");
 Evas_Object *body=elm_entry_add(p->popup);elm_entry_editable_set(body,EINA_FALSE);elm_entry_scrollable_set(body,EINA_TRUE);elm_entry_line_wrap_set(body,ELM_WRAP_WORD);label(body,message);Evas_Object *holder=elm_table_add(p->popup);Evas_Object *spacer=evas_object_rectangle_add(evas_object_evas_get(holder));evas_object_color_set(spacer,0,0,0,0);evas_object_size_hint_min_set(spacer,620,320);evas_object_pass_events_set(spacer,EINA_TRUE);elm_table_pack(holder,spacer,0,0,1,1);evas_object_show(spacer);evas_object_size_hint_weight_set(body,EVAS_HINT_EXPAND,EVAS_HINT_EXPAND);evas_object_size_hint_align_set(body,EVAS_HINT_FILL,EVAS_HINT_FILL);elm_table_pack(holder,body,0,0,1,1);elm_object_content_set(p->popup,holder);evas_object_show(body);evas_object_show(holder);
 Evas_Object *accept=elm_button_add(p->popup);elm_object_text_set(accept,"Confirm");evas_object_smart_callback_add(accept,"clicked",confirm_operation,p);elm_object_part_content_set(p->popup,"button1",accept);
 Evas_Object *cancel=elm_button_add(p->popup);elm_object_text_set(cancel,"Cancel");evas_object_smart_callback_add(cancel,"clicked",cancel_operation,p);elm_object_part_content_set(p->popup,"button2",cancel);elm_win_activate(win);evas_object_show(p->popup);}
static void apply_clicked(void *data,Evas_Object *obj,void *event){(void)data;(void)obj;(void)event;if(!review_file)return;FILE *f=fopen(review_file,"r");if(!f)return;char *json=calloc(2*1024*1024+1,1);size_t n=fread(json,1,2*1024*1024,f);fclose(f);json[n]=0;ask_operation("apply",json,review_text?review_text:"Review package changes before applying.");free(json);}
static void reload_clicked(void *data,Evas_Object *obj,void *event){(void)data;(void)obj;(void)event;ask_operation("reload","null","Fetch fresh indexes from all enabled repositories, then refresh package results and available upgrades. This does not install or upgrade packages. Any existing transaction preview will be invalidated.");}
static void source_picked(void *data,Evas_Object *obj,void *event){(void)obj;(void)event;source_selected=data;label(source_url,source_selected->url);}
static void source_closed(void *data,Evas_Object *obj,void *event){(void)data;(void)obj;(void)event;source_win=source_list=source_url=source_info=NULL;source_selected=NULL;Source *s;EINA_LIST_FREE(source_rows,s){free(s->url);free(s->id);free(s->name);free(s);}}
static void source_change(void *data,Evas_Object *obj,void *event){(void)obj;(void)event;const char *action=data;if(operation_request.exe||plan_request.exe)return;int add=!strcmp(action,"add"),trust=!strcmp(action,"trust");if(!add&&!source_selected)return;
 if(!add&&!trust&&source_selected->known){label(source_info,"Select a configured source for enable, disable or remove. Use Add for known sources.");return;}
 if(trust&&(!source_selected->known||strcmp(source_selected->id,"companion"))){label(source_info,"Only the vetted companion-feed key is available here. Custom key trust requires separate verification.");return;}
 char *json=NULL,*message=NULL;size_t size=0;FILE *f=open_memstream(&json,&size);if(trust)json_string(f,"companion");else{fprintf(f,"{\"action\":\"%s\",\"digest\":\"%s\"",action,source_digest);if(add){char *url=elm_entry_markup_to_utf8(elm_entry_entry_get(source_url));fputs(",\"url\":",f);json_string(f,url?url:"");free(url);}else fprintf(f,",\"index\":%d",source_selected->index);fputc('}',f);}fclose(f);
 if(trust)message=strdup("Trust the AlpinE companion-feed APK signing key?\n\nbuilder-6acd560b.rsa.pub\nSHA256 f308145bc1a64270e85f58d8af810015a5e2605a5bba1ddbeb2f86da65a42bd4\n\nThe helper fetches the public key over HTTPS and verifies this exact fingerprint. This permits packages signed by that publisher; it does not enable the feed or install software.");
 else{char *target=add?elm_entry_markup_to_utf8(elm_entry_entry_get(source_url)):strdup(source_selected->url);asprintf(&message,"Repository operation: %s\n\nSource: %s\n\nExisting source comments and tags are preserved. Source changes do not trust new signing keys or install packages. Reload afterward to fetch current indexes. Cross-release additions are rejected by this interface.",action,target?target:"");free(target);}
 ask_operation(trust?"trust":"source",json,message);free(json);free(message);}
static void accept_sources(char *text){if(source_win){Evas_Object *old=source_win;source_closed(NULL,NULL,NULL);evas_object_del(old);}source_win=elm_win_util_standard_add("enaptic-repositories","Enaptic — Repositories");evas_object_size_hint_min_set(source_win,820,600);elm_win_autodel_set(source_win,EINA_TRUE);evas_object_smart_callback_add(source_win,"delete,request",source_closed,NULL);
 Evas_Object *outer=box(source_win,0);elm_win_resize_object_add(source_win,outer);source_list=elm_list_add(source_win);evas_object_size_hint_weight_set(source_list,EVAS_HINT_EXPAND,EVAS_HINT_EXPAND);evas_object_size_hint_align_set(source_list,EVAS_HINT_FILL,EVAS_HINT_FILL);evas_object_size_hint_min_set(source_list,-1,180);pack(outer,source_list);
 char *rest=text,*line;while((line=strsep(&rest,"\n"))){if(!strcmp(line,"TEXT"))break;char *part=line,*type=strsep(&part,"\t");if(!strcmp(type,"DIGEST")){snprintf(source_digest,sizeof(source_digest),"%s",part?part:"");continue;}Source *s=calloc(1,sizeof(*s));char caption[2400];if(!strcmp(type,"SOURCE")){char *index=strsep(&part,"\t"),*enabled=strsep(&part,"\t");if(!index||!enabled||!part){free(s);continue;}s->index=atoi(index);s->enabled=atoi(enabled);s->url=strdup(part);s->id=strdup("");s->name=strdup(part);snprintf(caption,sizeof(caption),"Configured [%s]  %s",s->enabled?"enabled":"disabled",s->url);}else if(!strcmp(type,"KNOWN")){char *id=strsep(&part,"\t"),*name=strsep(&part,"\t"),*url=strsep(&part,"\t");if(!id||!name||!url){free(s);continue;}s->known=1;s->id=strdup(id);s->name=strdup(name);s->url=strdup(url);snprintf(caption,sizeof(caption),"Known source: %s — %s",name,url);}else{free(s);continue;}source_rows=eina_list_append(source_rows,s);elm_list_item_append(source_list,caption,NULL,NULL,source_picked,s);}
 elm_list_go(source_list);source_url=elm_entry_add(source_win);elm_entry_single_line_set(source_url,EINA_TRUE);elm_entry_scrollable_set(source_url,EINA_TRUE);elm_object_part_text_set(source_url,"guide","Select a known source or enter an HTTPS repository URL");evas_object_size_hint_weight_set(source_url,EVAS_HINT_EXPAND,0);evas_object_size_hint_align_set(source_url,EVAS_HINT_FILL,.5);pack(outer,source_url);
 Evas_Object *tools=box(source_win,1);evas_object_size_hint_weight_set(tools,EVAS_HINT_EXPAND,0);pack(outer,tools);button(tools,"Enable",source_change,"enable");button(tools,"Disable",source_change,"disable");button(tools,"Remove",source_change,"remove");button(tools,"Add URL / Known",source_change,"add");button(tools,"Trust Companion Key",source_change,"trust");button(tools,"Reload Indexes",reload_clicked,NULL);
 source_info=elm_entry_add(source_win);elm_entry_editable_set(source_info,EINA_FALSE);elm_entry_scrollable_set(source_info,EINA_TRUE);elm_entry_line_wrap_set(source_info,ELM_WRAP_WORD);evas_object_size_hint_weight_set(source_info,EVAS_HINT_EXPAND,EVAS_HINT_EXPAND);evas_object_size_hint_align_set(source_info,EVAS_HINT_FILL,EVAS_HINT_FILL);evas_object_size_hint_min_set(source_info,600,180);label(source_info,rest?rest:"");pack(outer,source_info);evas_object_resize(source_win,920,650);evas_object_show(source_win);}
